#include <LiquidCrystal.h>

// === ПИНЫ LCD ===
// RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

// === ПЕРЕМЕННЫЕ ДЛЯ ВРЕМЕНИ ===
int hours = 12;      // Часы (можно изменить на любое время)
int minutes = 0;     // Минуты
int seconds = 0;     // Секунды

unsigned long lastTime = 0; // Для отслеживания секунд

void setup() {
  // Инициализация дисплея (16 символов, 2 строки)
  lcd.begin(16, 2);

  // Вывод приветствия
  lcd.print("Hello!");
  delay(1000);
  lcd.clear();
}

void loop() {
  // === ОБНОВЛЕНИЕ ВРЕМЕНИ (каждую секунду) ===
  if (millis() - lastTime >= 1000) {
    lastTime = millis(); // Запоминаем время последнего обновления

    seconds++; // Добавляем 1 секунду

    if (seconds >= 60) {
      seconds = 0;
      minutes++;
    }
    if (minutes >= 60) {
      minutes = 0;
      hours++;
    }
    if (hours >= 24) {
      hours = 0; // Новый день
    }
  }

  // === ВЫВОД НА ЭКРАН ===

  // Строка 1: Время (ЧЧ:ММ:СС)
  lcd.setCursor(0, 0);
  lcd.print("Time: ");

  if (hours < 10) lcd.print("0");
  lcd.print(hours);
  lcd.print(":");

  if (minutes < 10) lcd.print("0");
  lcd.print(minutes);
  lcd.print(":");

  if (seconds < 10) lcd.print("0");
  lcd.print(seconds);

  // Строка 2: Дата (можно изменить)
  lcd.setCursor(0, 1);
  lcd.print("Date: 09/09/2026");
}
